sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    if (!current.assigned_to) {
        return;
    }

    // On update, only re-check when a relevant field actually changed
    if (!current.isNewRecord()) {
        var relevantChange = current.assigned_to.changes() || current.start_time.changes() || current.end_time.changes();
        if (!relevantChange) {
            return;
        }
    }

    var newStart = current.start_time;
    var newEnd = current.end_time;
    if (!newStart || !newEnd) {
        return;
    }

    var buddyId = current.assigned_to.toString();

    // Find the buddy's schedule container(s)
    var schedGr = new GlideRecord('cmn_schedule');
    schedGr.addQuery('x_travel_buddy_app_u_buddy_profile', buddyId);
    schedGr.query();

    while (schedGr.next()) {
        var conflict = new GlideRecord('cmn_schedule_span');
        conflict.addQuery('schedule', schedGr.getUniqueValue());
        conflict.addQuery('type', 'Booked');
        conflict.addQuery('u_start_date_time', '<=', newEnd);
        conflict.addQuery('u_end_date_time', '>=', newStart);
        conflict.addNotNullQuery('u_start_date_time');
        conflict.addNotNullQuery('u_end_date_time');
        // Exclude this trip's own linked span, if any (relevant on update of an already-booked trip)
        if (!current.isNewRecord()) {
            conflict.addQuery('x_travel_buddy_app_u_linked_trip', '!=', current.sys_id.toString());
        }
        conflict.query();
        if (conflict.hasNext()) {
            gs.addErrorMessage('This Buddy already has a booked trip that overlaps these dates. Please choose different dates or assign a different Buddy.');
            current.setAbortAction(true);
            return;
        }
    }

})(current, previous);
